//! BMODULE.MRG attack effects hand-ported: the registry of ported cards and
//! the frame they run in. A BMODULE record is indexed by card id (< 683);
//! its entry comes from the executable's type-1 table 0x2B94C0 by monster
//! model index (u16 0x2CE024[model] = card, 854 models); its data area is
//! 0x1ED0000; launch `entry(data, 0)`, each later update `entry(data, -1)`
//! until it returns 8 [F the project notes].
//!
//! Every card < 683 is in [`PORTED`] (the test below). A card that cannot
//! load has no attack effect; nothing else runs in its place.
use crate::bus::{Bus, Image};
use crate::exe::Fx;
use crate::types::{EffectTextures, EffectUpdate, EffectWorld};
use crate::EffectPort;
use std::sync::Arc;

/// The type-1 task's data area.
pub const DATA_AREA: u32 = 0x01ED_0000;
const RECORD_BYTES: usize = 0x8000;
const MODEL_CARD_TABLE: u32 = 0x002C_E024;
const MODEL_COUNT: u16 = 854;

/// A ported program: `entry(fx, param)` -> the return code.
pub type Program = fn(&mut Fx, i32) -> i32;

