/// The port of `card`'s program, if any.
pub fn program(card: u16) -> Option<Program> {
    PORTED.iter().find(|p| p.0 == card).map(|p| p.2)
}

/// The monster model index of `card` (the first model whose u16
/// 0x2CE024[model] is the card).
pub fn model_index(image: &Image, card: u16) -> Option<u16> {
    if card >= 683 {
        return None;
    }
    (0..MODEL_COUNT).find(|&m| {
        let a = MODEL_CARD_TABLE + 2 * u32::from(m);
        u16::from_le_bytes([image.byte(a), image.byte(a + 1)]) == card
    })
}

/// A running ported attack effect.
#[derive(Clone)]
pub struct BPort {
    fx: Fx,
    program: Program,
    pub card: u16,
    pub model: u16,
}

impl BPort {
    /// `card`'s ported program with the user's BMODULE record (`None`: not
    /// ported, no model index, or no record). `handles`: the attacker's and
    /// the defender's (side << 8 | slot).
    pub fn load(image: Arc<Image>, bmodule: &[u8], card: u16, handles: [u16; 2], textures: &EffectTextures) -> Option<Self> {
        let program = program(card)?;
        let start = usize::from(card) * RECORD_BYTES;
        let record = bmodule.get(start..start + RECORD_BYTES)?;
        if record.get(..4) != Some(b"MWo3") {
            return None;
        }
        let model = model_index(&image, card)?;
        let fx = Fx::new(image, record, model, handles, textures);
        Some(Self { fx, program, card, model })
    }
}

impl EffectPort for BPort {
    fn update(&mut self, world: &dyn EffectWorld) -> EffectUpdate {
        if self.fx.finished {
            return EffectUpdate { ret: 8, ..Default::default() };
        }
        self.fx.begin(world);
        let arg = if self.fx.calls == 0 { 0 } else { -1 };
        let ret = (self.program)(&mut self.fx, arg);
        self.fx.end(ret)
    }
    fn calls(&self) -> usize {
        self.fx.calls
    }
    fn finished(&self) -> bool {
        self.fx.finished
    }
    fn rand_state(&mut self) -> u64 {
        self.fx.rand_state()
    }
    fn set_rand_state(&mut self, state: u64) {
        self.fx.set_rand_state(state);
    }
    fn bus(&mut self) -> Option<&mut dyn Bus> {
        Some(&mut self.fx.mem)
    }
}

/// b737 (card 671): returns 8 at once, every call (`jr ra; li v0, 8` at
/// 0x1E00080) [F].
fn b737(_: &mut Fx, _: i32) -> i32 {
    8
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_card_has_exactly_one_ported_row() {
        let missing: Vec<u16> = (0..683).filter(|&c| program(c).is_none()).collect();
        assert!(missing.is_empty(), "cards with no PORTED row: {missing:?}");
        assert_eq!(PORTED.len(), 683, "a card out of range or a duplicate row");
    }
}
